import { navigate } from "gatsby";
import React, { useEffect, useState } from "react";
import type { Quote, QuoteStatus, UserProfile } from "../types";
import {
  createQuote,
  getQuoteById,
  updateQuote,
} from "../../../sessionServices/quotes/quotesService";
import { listUsers } from "../../../sessionServices/users/usersService";
import { writeAuditLog } from "../../../sessionServices/audit/auditLogsService";
import { useAuth } from "../../auth/AuthContext";

interface Props {
  quoteId?: string;
}

const STATUSES: QuoteStatus[] = ["draft", "sent", "approved", "rejected", "expired"];

export function QuoteForm({ quoteId }: Props) {
  const { user } = useAuth();
  const isEdit = !!quoteId;

  const [users, setUsers] = useState<UserProfile[]>([]);
  const [userId, setUserId] = useState("");
  const [title, setTitle] = useState("");
  const [status, setStatus] = useState<QuoteStatus>("draft");
  const [validUntil, setValidUntil] = useState("");
  const [internalNotes, setInternalNotes] = useState("");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function load() {
      const [usersData, quoteData] = await Promise.all([
        listUsers(),
        isEdit ? getQuoteById(quoteId!) : Promise.resolve(null),
      ]);
      setUsers(usersData);
      if (quoteData) {
        setUserId(quoteData.userId);
        setTitle(quoteData.title);
        setStatus(quoteData.status);
        setInternalNotes(quoteData.internalNotes ?? "");
        if (quoteData.validUntil) {
          const d = (quoteData.validUntil as { toDate: () => Date }).toDate();
          setValidUntil(d.toISOString().slice(0, 10));
        }
      }
    }
    load();
  }, [quoteId]);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!user) return;
    if (!userId || !title.trim()) {
      setError("Client and title are required.");
      return;
    }
    setSaving(true);
    setError(null);
    try {
      if (isEdit) {
        await updateQuote(quoteId!, {
          title: title.trim(),
          status,
          validUntil: validUntil || undefined,
          internalNotes: internalNotes.trim() || undefined,
          updatedBy: user.uid,
        });
        await writeAuditLog({
          entityType: "quote",
          entityId: quoteId!,
          action: "update",
          after: { title, status },
          performedBy: user.uid,
        });
        navigate(`/admin/quotes/${quoteId}`);
      } else {
        const id = await createQuote({
          userId,
          title: title.trim(),
          validUntil: validUntil || undefined,
          internalNotes: internalNotes.trim() || undefined,
          createdBy: user.uid,
        });
        await writeAuditLog({
          entityType: "quote",
          entityId: id,
          action: "create",
          after: { userId, title },
          performedBy: user.uid,
        });
        navigate(`/admin/quotes/${id}`);
      }
    } catch {
      setError("Could not save the quote. Please try again.");
      setSaving(false);
    }
  }

  const fieldCls = "w-full rounded-lg border border-gray-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-gray-400";

  return (
    <form onSubmit={handleSubmit} className="space-y-5 rounded-xl bg-white p-6 shadow-sm ring-1 ring-gray-200 max-w-2xl">
      <h2 className="text-base font-semibold text-gray-900">
        {isEdit ? "Edit quote" : "New quote"}
      </h2>

      <div className="space-y-1">
        <label className="text-xs font-medium text-gray-600">Client *</label>
        <select value={userId} onChange={(e) => setUserId(e.target.value)} className={fieldCls} required>
          <option value="">Select a client…</option>
          {users.map((u) => (
            <option key={u.uid} value={u.uid}>
              {u.fullName} ({u.email})
            </option>
          ))}
        </select>
      </div>

      <div className="space-y-1">
        <label className="text-xs font-medium text-gray-600">Title *</label>
        <input
          type="text"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder="e.g. Travel package Cancún 2026"
          className={fieldCls}
          required
        />
      </div>

      {isEdit && (
        <div className="space-y-1">
          <label className="text-xs font-medium text-gray-600">Status</label>
          <select value={status} onChange={(e) => setStatus(e.target.value as QuoteStatus)} className={fieldCls}>
            {STATUSES.map((s) => (
              <option key={s} value={s}>{s}</option>
            ))}
          </select>
        </div>
      )}

      <div className="space-y-1">
        <label className="text-xs font-medium text-gray-600">Valid until</label>
        <input
          type="date"
          value={validUntil}
          onChange={(e) => setValidUntil(e.target.value)}
          className={fieldCls}
        />
      </div>

      <div className="space-y-1">
        <label className="text-xs font-medium text-gray-600">Internal notes</label>
        <textarea
          value={internalNotes}
          onChange={(e) => setInternalNotes(e.target.value)}
          rows={3}
          className={fieldCls}
        />
      </div>

      {error && <p className="text-xs text-red-600">{error}</p>}

      <div className="flex gap-3">
        <button
          type="submit"
          disabled={saving}
          className="rounded-lg bg-gray-900 px-5 py-2 text-sm font-medium text-white transition hover:bg-gray-700 disabled:opacity-60"
        >
          {saving ? "Saving…" : isEdit ? "Save changes" : "Create quote"}
        </button>
        <button
          type="button"
          onClick={() => navigate(isEdit ? `/admin/quotes/${quoteId}` : "/admin/quotes")}
          className="rounded-lg border border-gray-300 px-5 py-2 text-sm font-medium text-gray-700 transition hover:bg-gray-100"
        >
          Cancel
        </button>
      </div>
    </form>
  );
}
