import {
  addDoc,
  collection,
  deleteDoc,
  doc,
  getDoc,
  getDocs,
  orderBy,
  query,
  serverTimestamp,
  Timestamp,
  updateDoc,
  where,
} from "firebase/firestore";
import type { Quote, QuoteStatus } from "../../features/admin/types";

export type CreateQuoteInput = {
  userId: string;
  title: string;
  validUntil?: string;
  internalNotes?: string;
  createdBy: string;
};

export type UpdateQuoteInput = Partial<Omit<CreateQuoteInput, "createdBy" | "userId">> & {
  updatedBy: string;
  status?: QuoteStatus;
};

async function getDb() {
  const { db } = await import("../../lib/firebase");
  return db;
}

export async function createQuote(input: CreateQuoteInput): Promise<string> {
  const db = await getDb();
  const ref = await addDoc(collection(db, "quotes"), {
    userId: input.userId,
    title: input.title,
    status: "draft" as QuoteStatus,
    validUntil: input.validUntil
      ? Timestamp.fromDate(new Date(input.validUntil))
      : null,
    internalNotes: input.internalNotes ?? null,
    shareToken: null,
    sharedAt: null,
    createdAt: serverTimestamp(),
    updatedAt: serverTimestamp(),
    createdBy: input.createdBy,
    updatedBy: null,
  });
  return ref.id;
}

export async function updateQuote(id: string, input: UpdateQuoteInput): Promise<void> {
  const db = await getDb();
  const { validUntil, ...rest } = input;
  const payload: Record<string, unknown> = { updatedAt: serverTimestamp() };
  for (const [key, value] of Object.entries(rest)) {
    payload[key] = value ?? null;
  }
  if (validUntil !== undefined) {
    payload["validUntil"] = validUntil ? Timestamp.fromDate(new Date(validUntil)) : null;
  }
  await updateDoc(doc(db, "quotes", id), payload);
}

export async function getQuoteById(id: string): Promise<(Quote & { id: string }) | null> {
  const db = await getDb();
  const snap = await getDoc(doc(db, "quotes", id));
  if (!snap.exists()) return null;
  return { id: snap.id, ...(snap.data() as Quote) };
}

export async function getQuoteByToken(token: string): Promise<(Quote & { id: string }) | null> {
  const db = await getDb();
  const q = query(collection(db, "quotes"), where("shareToken", "==", token));
  const snap = await getDocs(q);
  if (snap.empty) return null;
  const d = snap.docs[0];
  return { id: d.id, ...(d.data() as Quote) };
}

export async function listQuotes(): Promise<(Quote & { id: string })[]> {
  const db = await getDb();
  const q = query(collection(db, "quotes"), orderBy("createdAt", "desc"));
  const snap = await getDocs(q);
  return snap.docs.map((d) => ({ id: d.id, ...(d.data() as Quote) }));
}

export async function listQuotesByUser(userId: string): Promise<(Quote & { id: string })[]> {
  const db = await getDb();
  const q = query(
    collection(db, "quotes"),
    where("userId", "==", userId),
    orderBy("createdAt", "desc")
  );
  const snap = await getDocs(q);
  return snap.docs.map((d) => ({ id: d.id, ...(d.data() as Quote) }));
}

export async function generateQuoteShareToken(quoteId: string, updatedBy: string): Promise<string> {
  const db = await getDb();
  const token = crypto.randomUUID();
  await updateDoc(doc(db, "quotes", quoteId), {
    shareToken: token,
    sharedAt: serverTimestamp(),
    status: "sent" as QuoteStatus,
    updatedAt: serverTimestamp(),
    updatedBy,
  });
  return token;
}

export async function revokeQuoteShareToken(quoteId: string, updatedBy: string): Promise<void> {
  const db = await getDb();
  await updateDoc(doc(db, "quotes", quoteId), {
    shareToken: null,
    sharedAt: null,
    updatedAt: serverTimestamp(),
    updatedBy,
  });
}

export async function deleteQuote(id: string): Promise<void> {
  const db = await getDb();
  await deleteDoc(doc(db, "quotes", id));
}
